import{z as i,x as o,o as e,c as p,q as r,j as s,D as B,d as a,s as n,S as l,b as A}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"版本与审批","description":"","frontmatter":{"title":"版本与审批","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/sl-versioning-approval.md","filePath":"quant/sl-versioning-approval.md","lastUpdated":1791413859000}'),d={name:"quant/sl-versioning-approval.md"};function C(D,E,F,h,u,f){const t=o("Mermaid");return e(),p("div",null,[E[2]||(E[2]=r('<h1 id="版本与审批" tabindex="-1">版本与审批 <a class="header-anchor" href="#版本与审批" aria-label="Permalink to &quot;版本与审批&quot;">​</a></h1><div class="epigraph"><p>有效挑战是贯穿的原则：审查者必须独立于开发，并且有能力、有动力提出实质性反对，否则审批只是签字。</p><footer>—— 据 Federal Reserve SR 11-7（2011）关于有效挑战的表述整理</footer></div><p><a href="/quant/sl-registry">上一课</a>把策略台账立成状态机：每个策略一个 id，阶段转移挂在判据上。但把一个版本送过转移边的组织动作——谁评、谁批、批的到底是什么、批准管多久——还没有定义。本课写版本与审批：版本是台账里「不可变工件」的落地形式，审批是对「判据与声明仍然成立」的独立复核。后课的容量与衰减治理，都以「批准的是哪条曲线、哪个预算带」为起点。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>没有版本纪律的实盘会自己长出第六课要禁止的一切：参数被顺手改过但没升版，实盘跑的东西与台账登记的对不上；批准记录只写「委员会同意」，没人知道批准基于哪份回测、哪条容量声明；出了事想回滚，却找不到当时跑的究竟是哪个工件。缺口因此有两层：<strong>版本</strong>要回答「此刻在跑的是什么」，<strong>审批</strong>要回答「凭什么让它跑」。二者缺一，台账的指针链在第一环就断。</p><p><span class="marginnote">直觉类比：版本三元组像快递的封箱贴——代码、数据、配置各贴一条不可撕换的封条，审批批的是这一整箱，不是「这个思路」。事后谁也不能说「箱子里其实是另一批货」：封条对不上就当场穿帮。</span></p><p>把改动分类是第一道纪律：影响信号生成、宇宙选择、或执行侧冲击假设的任何代码与参数变化，必须升版并重走判据；纯文案、监控阈值微调走轻量变更单。分类标准预先写死，否则「只是调个参数」会成为永久漏洞。</p><p><span class="marginnote">常见误区：初学者容易把「只是调个参数」当成不用升版的小事。参数一改，信号就换了——同一套判据重算的结果可以完全不同。分类标准预写死的全部意义，就是不让这句话成为绕过判据的永久后门。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>一个版本是三元组的哈希：代码提交、数据快照、配置。三者都不可变，版本号递增即可，不必语义化。提交包至少附四样：判据引用（挂到台账转移边）、当前 \\(N\\) 与累计范围、容量曲线声明、衰减预算带。审批流三站：研究者提交；独立复核——复核者不在提案人汇报线上，复算判据而不是复述结论，这正是 SR 11-7 要求的独立性、能力与激励；风险与合规会签。批准记录入台账，且批准的对象是「在某判据、某容量档、某衰减预算下运行至某有效期」，不是「这个策略好」。</p><p>回滚走同一套机制：台账把实盘指针指回旧版本即可，旧工件因不可变而仍然可复现；回滚同样留痕。<a href="/quant/research-sim-prod">研究-模拟-实盘隔离</a>的口径在这里继续成立：回滚是默认动作，与晋级共用指标带，不该比晋级更难。</p>',11)),(e(),s(l,null,{default:B(()=>[n(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20SUB%5B%22%E6%8F%90%E4%BA%A4%EF%BC%9A%E5%B7%A5%E4%BB%B6%E4%B8%89%E5%85%83%E7%BB%84%20%2B%20%E5%88%A4%E6%8D%AE%20%2B%20N%20%2B%20%E5%A3%B0%E6%98%8E%22%5D%20--%3E%20REV%5B%22%E7%8B%AC%E7%AB%8B%E5%A4%8D%E6%A0%B8%EF%BC%9A%E5%A4%8D%E7%AE%97%E5%88%A4%E6%8D%AE%EF%BC%8C%E6%A0%B8%20N%20%E4%B8%8E%E5%A3%B0%E6%98%8E%22%5D%0A%20%20REV%20--%3E%7C%E9%A9%B3%E5%9B%9E%7C%20TICKET%5B%22%E9%A9%B3%E5%9B%9E%E7%90%86%E7%94%B1%E5%85%A5%E5%A4%B1%E8%B4%A5%E6%B8%85%E5%8D%95%EF%BC%8CN%20%E4%B8%8D%E6%B8%85%E9%9B%B6%22%5D%0A%20%20REV%20--%3E%7C%E9%80%9A%E8%BF%87%7C%20SIGN%5B%22%E9%A3%8E%E9%99%A9%E4%B8%8E%E5%90%88%E8%A7%84%E4%BC%9A%E7%AD%BE%22%5D%0A%20%20SIGN%20--%3E%20OK%5B%22%E6%89%B9%E5%87%86%E5%85%A5%E5%8F%B0%E8%B4%A6%EF%BC%9A%E5%88%A4%E6%8D%AE%E3%80%81%E5%AE%B9%E9%87%8F%E6%A1%A3%E3%80%81%E9%A2%84%E7%AE%97%E5%B8%A6%E3%80%81%E6%9C%89%E6%95%88%E6%9C%9F%22%5D%0A%20%20OK%20--%3E%20LIVE%5B%22%E5%AE%9E%E7%9B%98%E6%8C%87%E9%92%88%E6%8C%87%E5%90%91%E8%AF%A5%E7%89%88%E6%9C%AC%22%5D%0A%20%20EXPIRE%5B%22%E5%88%B0%E6%9C%9F%E5%A4%8D%E5%AE%A1%EF%BC%9A%E4%B8%8D%E5%A4%8D%E4%BD%8D%E5%8D%B3%E8%87%AA%E5%8A%A8%E5%81%9C%E6%96%B0%E5%A2%9E%22%5D%20--%3E%20REV%0A"})]),fallback:B(()=>[...E[0]||(E[0]=[a(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=A("h2",{id:"机制",tabindex:"-1"},[a("机制 "),A("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=A("p",null,[a("独立复核为什么不能省：研究者对自己的策略有系统性乐观，这一点无法靠自觉抵消；更关键的是，"),A("a",{href:"/quant/multiple-testing-factors"},"多重检验折价"),a("只有在复算时才可见——复核者要核的不是「回测夏普多高」，而是这已是同谱系第几次试验、"),A("a",{href:"/quant/deflated-sharpe"},"缩减后的统计量"),a("还剩多少。批准记录里的有效期是审批与持续监测的接口：SR 11-7 的验证不是一次性证书，用途或环境变了就要复审；过期不复审即自动降级，防止「十年前批过的策略」永远挂在实盘。")],-1)),(e(),s(l,null,{default:B(()=>[n(t,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20CLAIM%5B%22%E6%8F%90%E4%BA%A4%E6%96%B9%E7%94%B3%E6%8A%A5%EF%BC%9A%E5%9B%9E%E6%B5%8B%E5%A4%8F%E6%99%AE%E5%BE%88%E9%AB%98%22%5D%20--%3E%20Q%7B%22%E7%8B%AC%E7%AB%8B%E5%A4%8D%E6%A0%B8%E6%A0%B8%E4%BB%80%E4%B9%88%3F%22%7D%0A%20%20Q%20--%3E%20NQ%5B%22%E8%B0%B1%E7%B3%BB%E8%AE%A1%E6%95%B0%EF%BC%9A%E8%BF%99%E5%B7%B2%E6%98%AF%E7%AC%AC%E5%87%A0%E6%AC%A1%E8%AF%95%E9%AA%8C%EF%BC%8CN%20%E4%B8%8E%E7%B4%AF%E8%AE%A1%E8%8C%83%E5%9B%B4%22%5D%0A%20%20Q%20--%3E%20DSHR%5B%22%E7%BC%A9%E5%87%8F%E7%BB%9F%E8%AE%A1%E9%87%8F%EF%BC%9A%E6%8C%89%E7%B4%AF%E8%AE%A1%20N%20%E6%8A%98%E5%87%8F%E5%90%8E%E8%BF%98%E5%89%A9%E5%A4%9A%E5%B0%91%22%5D%0A%20%20Q%20--%3E%20DECL%5B%22%E5%A3%B0%E6%98%8E%E4%B8%80%E8%87%B4%E6%80%A7%EF%BC%9A%E5%AE%B9%E9%87%8F%E6%9B%B2%E7%BA%BF%E4%B8%8E%E8%A1%B0%E5%87%8F%E5%B8%A6%E5%AF%B9%E5%BE%97%E4%B8%8A%E5%90%97%22%5D%0A%20%20NQ%20--%3E%20VERDICT%5B%22%E6%89%B9%E5%87%86%E5%AF%B9%E8%B1%A1%EF%BC%9A%E5%88%A4%E6%8D%AE%E3%80%81%E5%AE%B9%E9%87%8F%E6%A1%A3%E3%80%81%E9%A2%84%E7%AE%97%E5%B8%A6%E3%80%81%E6%9C%89%E6%95%88%E6%9C%9F%22%5D%0A%20%20DSHR%20--%3E%20VERDICT%0A%20%20DECL%20--%3E%20VERDICT%0A"})]),fallback:B(()=>[...E[1]||(E[1]=[a(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=r('<p><span class="marginnote">数字实例：同一思路第 20 次试验，若每次按 5% 的显著性水平判断，「至少一次碰巧显著」的概率是 \\(1-0.95^{20}\\approx 64\\%\\)。复核者若只看本次夏普、不核谱系 \\(N\\)，就有六成多的可能在为运气签字——复算先问「第几次」，原因在此。</span></p><p><span class="marginnote">批准记录里最该写清的是驳回理由：驳回理由进入失败清单，同一思路换个包装再来时，\\(N\\) 才不会清零——这是审批对多重检验保护的直接贡献。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>审批不创造信息，它核对的是判据与声明的一致性：判据本身要过不过，在研究阶段的<a href="/quant/econ-vs-stat-sig">统计与经济显著性</a>里已经定过。轻量通道与升版通道要真的分开，否则两头堵：小事走全套审批，研究会被官僚拖死；大事走轻量通道，版本纪律形同虚设。紧急停机不需要审批——监测状态机已经预授权，事后补记录即可；审批管的是「往回送」，不是「停下来」。审批记录的论证写作与归档格式，是研究复盘课的对象，本课只保证指针不断。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>版本是不可变工件三元组的哈希；影响信号、宇宙或冲击假设的改动必须升版。</li><li>审批是独立复核判据与声明，不是对人的信任；独立、有能力、有激励三条件缺一不可。</li><li>批准的对象是判据、容量档、预算带与有效期，批准记录入台账并可审计。</li><li>回滚是指针回拨，与晋级同样容易；过期不复审自动降级。</li><li>出处：有效挑战与持续验证原则据 Federal Reserve SR 11-7（2011）整理；多重检验保护见<a href="/quant/multiple-testing-factors">因子多重检验</a>与<a href="/quant/deflated-sharpe">缩减夏普</a>，回滚默认见<a href="/quant/paper-to-live-staging">研究-模拟-实盘三级台阶</a>。</li></ul>',6))])}const _=i(d,[["render",C]]);export{c as __pageData,_ as default};
